def postfix_to_prefix(postfix):
    stack = []
    for ch in postfix:
        if ch in "+-*/":
            b, a = stack.pop(), stack.pop()
            stack.append(ch + a + b)
        else:
            stack.append(ch)
    return stack[0]
```

