def count_primes(n):
    if n < 2:
        return 0
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n ** 0.5) + 1):
        if is_prime[p]:
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False
    return sum(is_prime)
```

```python
def remove_duplicates_keep_two(nums):
    if not nums:
        return []
    i = 0
    for j in range(len(nums)):
        if i < 2 or nums[j] != nums[i - 2]:
            nums[i] = nums[j]
            i += 1
    return nums[:i]
```

