def manhattan_after_moves(moves):
    x = y = 0
    for m in moves:
        if m == 'N':
            y += 1
        elif m == 'S':
            y -= 1
        elif m == 'E':
            x += 1
        elif m == 'W':
            x -= 1
    return abs(x) + abs(y)
```

```python
def ocean_view_indices(heights):
    stack = []
    result = []
    for i, h in enumerate(heights):
        while stack and heights[stack[-1]] <= h:
            stack.pop()
        if not stack:
            result.append(i)
        stack.append(i)
    return result
```

```python
def times_to_hundredths(times):
    import re
    result = []
    for t in times:
        m = re.fullmatch(r'(\d+):(\d{2})\.(\d{2})', t)
        if m:
            result.append(int(m.group(1)) * 6000 + int(m.group(2)) * 100 + int(m.group(3)))
    return result
```

```python
def longest_upper_run(code):
    best = ""
    cur = ""
    for ch in code:
        if ch.isupper():
            cur += ch
        else:
            if len(cur) > len(best):
                best = cur
            cur = ""
    if len(cur) > len(best):
        best = cur
    return best
```

