def parse_dollars(s):
    s = s.replace('$', '').replace(',', '')
    dollars, cents = s.split('.') if '.' in s else (s, '00')
    return int(dollars) * 100 + int(cents.ljust(2, '0')[:2])
```

```python
def grade_bounds(grades):
    if len(grades) == 1:
        return (grades[0], grades[0])
    low, high = grade_bounds(grades[:-1])
    return (min(low, grades[-1]), max(high, grades[-1]))
```

```python
def max_points_with_duplicates(nums):
    counts = {}
    for n in nums:
        counts[n] = counts.get(n, 0) + 1
    dp = [0] * (max(counts) + 2)
    for v in range(1, len(dp)):
        dp[v] = max(dp[v - 1], dp[v - 2] + v * counts.get(v, 0))
    return dp[-1]
```

